import urllib.request
candidates=[
 'https://raw.githubusercontent.com/broadinstitute/gnomad_methods/main/gnomad/resources/grch38/gnomad.py',
 'https://raw.githubusercontent.com/broadinstitute/gnomad_qc/main/gnomad_qc/v3/resources/basics.py',
