 'https://raw.githubusercontent.com/broadinstitute/gnomad_qc/main/gnomad_qc/v4/resources/sample_qc.py',
]
for u in candidates:
    try:
        txt=urllib.request.urlopen(u, timeout=15).read().decode('utf-8','ignore')
        print('\\nURL',u,'len',len(txt))
        for line in txt.splitlines():
            if 'hgdp' in line.lower() or '1kg' in line.lower():
                print(line[:300])
    except Exception as e: print('ERR',u,e)
PY"

